import{_ as t,o as r,c as i,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Ceph Orchestrator Meeting 2022-06-21","description":"","frontmatter":{"title":"Ceph Orchestrator Meeting 2022-06-21","date":"2022-06-21T00:00:00.000Z","updated":"2022-06-28T00:00:00.000Z","tags":["Ceph","Distributed Storage","GANESHA","NFS","Failover"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2022/Ceph_Orchestrator_Meeting_2022-06-21.md","filePath":"posts/2022/Ceph_Orchestrator_Meeting_2022-06-21.md","lastUpdated":1780460162000}'),l={name:"posts/2022/Ceph_Orchestrator_Meeting_2022-06-21.md"};function s(p,e,a,n,_,g){return r(),i("div",null,[...e[0]||(e[0]=[o("<p>在2022年6月21日的Ceph Orchestrator会议中，与会者讨论了NFS和GANESHA集群的故障转移、部署和管理问题，以及CEPH和Rook项目间的集成。以下是会议的主要内容和决策：</p><ol><li><p><strong>GANESHA集群的故障转移</strong>：讨论了GANESHA集群在节点故障时可能无法运作的问题，并提出了使用ZAPFIMO实现自动故障转移的解决方案。</p></li><li><p><strong>NFS服务和客户端配置</strong>：探讨了NFS服务和客户端配置在同一主机上的位置问题，以及该问题对最佳实践的影响。</p></li><li><p><strong>CEPH与Rook项目的集成</strong>：讨论了Cepheiu与Rook项目未来集成方向，包括更新后的提案和测试计划。</p></li><li><p><strong>GANESHA和NFS协议理解</strong>：深入理解GANESHA和NFS协议，探讨它们在实际环境中的行为和预期。</p></li><li><p><strong>节点故障后的NFS操作处理</strong>：针对特定技术问题进行进一步调查，例如节点故障后如何处理已打开的NFS操作。</p></li><li><p><strong>现有解决方案评估</strong>：评估现有解决方案，并寻找改进方法以增强系统的稳定性和可用性。</p></li></ol><p>会议还讨论了以下技术细节：</p><ul><li>GANESHA集群配置和部署</li><li>Ceph Manager状态存储和获取存储功能</li><li>Keppler d配置变更</li><li>Ingress Spec的额外设置</li><li>Ganesha和Ingress Demon之间的连接</li><li>非本地绑定和虚拟IP的部署</li></ul><p>后续行动计划包括：</p><ul><li>对GANESHA和NFS协议的深入测试和验证</li><li>实施Ceph与Rook项目的集成</li><li>优化NFS服务和客户端配置</li><li>评估并实施故障转移解决方案</li></ul>",6)])])}const h=t(l,[["render",s]]);export{c as __pageData,h as default};
